{
  "contract": "Ring",
  "closure": {
    "site_function": "addLiquidity",
    "site_call": ".call",
    "functions": ["addLiquidity", "transfer", "transferFrom", "burn"],
    "justification": "The risk site in 'addLiquidity' exposes _balances, _inTaxSwap, _isLP, and _primaryLP during '.call'. Functions 'transfer', 'transferFrom', and 'burn' affect _balances, hence belong in the closure, since they can be called via .call due to their public/external visibility. '_sum__balances' is an alias for a mapping sum."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": ["transfer", "transferFrom", "burn"],
    "nesting_bound": {"addLiquidity": 1, "transfer": 0, "transferFrom": 0, "burn": 0}
  },
  "phases": {
    "function": "addLiquidity",
    "pre": {"name": "pre", "from_marker": "before addLiquidity", "to_marker": "call .call"},
    "exposed": {"name": "exposed", "from_marker": "call .call", "to_marker": "return .call"},
    "post": {"name": "post", "from_marker": "return .call", "to_marker": "after addLiquidity"},
    "linearization_point": "at return .call"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Amount in-flight during .call in addLiquidity",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "_sum__balances + _swapLimit == _totalSupply + inFlight",
    "stable_formula": "_sum__balances + _swapLimit == _totalSupply",
    "kind": "conserve"
  },
  "composition": {
    "target_property": "_sum__balances + _swapLimit == _totalSupply",
    "rule": "The invariant ensures that the sum of balances plus swap limit conserves the total supply across the callback window, accounting for in-flight actions."
  }
}
